import type { MultiSelectClearIconButtonProps } from "../multi-select.types";

import React from "react";
import { clsx } from "clsx";
import { Close as DefaultClearIcon } from "@exp-textura/icons";
import { IconButton } from "@components/icon-button";

import { MultiSelectClasses } from "../multi-select.styles";
import { useMultiSelect } from "../hooks/use-multi-select";

export const MultiSelectClearIconButton: React.FC<MultiSelectClearIconButtonProps> = ({
  children,
  className,
  "aria-label": customAriaLabel,
  hideWhenEmpty = true,
}) => {
  const { clearValue, value, triggerRef, disabled } = useMultiSelect();
  const buttonClasses = clsx(MultiSelectClasses.clearIconButton, className);

  const commonProps = {
    "aria-label": customAriaLabel || "clear all selected values",
  };

  if (value.length === 0 && hideWhenEmpty) {
    return null;
  }

  return (
    <IconButton
      buttonType="secondary"
      className={buttonClasses}
      disabled={disabled}
      size="sm"
      onClick={(e) => {
        e.stopPropagation();
        e.preventDefault();
        clearValue();
        triggerRef.current?.focus();
      }}
      onKeyDown={(e) => {
        e.stopPropagation();
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          clearValue();
          triggerRef.current?.focus();
        }
      }}
      onPointerDown={(e) => e.preventDefault()}
      {...commonProps}
    >
      {children || <DefaultClearIcon />}
    </IconButton>
  );
};

MultiSelectClearIconButton.displayName = "MultiSelect.ClearIconButton";
